      />
      <SimpleTable headers={["Not offered", "Why"]}>
       {data.unsupported.map((item) => (
        <tr key={item.what}>
         <td>{item.what}</td>
         <td>
          <span className="cell-dim">{item.why}</span>
         </td>
        </tr>
       ))}
      </SimpleTable>
     </Card>
    </>
   ) : null}
  </div>
 );
}

